<?php
require_once __DIR__.'/includes/functions.php';
$ids=array_values(array_unique(array_filter(array_map('intval',explode(',',(string)($_GET['ids']??''))),fn($x)=>$x>0)));if(count($ids)>4)$ids=array_slice($ids,0,4);
$cars=[];if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM cars WHERE is_active=1 AND id IN ($marks)");$s->execute($ids);$found=$s->fetchAll();$by=[];foreach($found as $c)$by[$c['id']]=$c;foreach($ids as $id)if(isset($by[$id]))$cars[]=$by[$id];}
$all=$pdo->query('SELECT id,name,brand FROM cars WHERE is_active=1 ORDER BY brand,name')->fetchAll();$fields=['Brand'=>'brand','Body type'=>'body_type','Ex-showroom starting price'=>'price_min','Price ceiling'=>'price_max','Fuel'=>'fuel','Transmission'=>'transmission','Engine / motor'=>'engine','Power'=>'power','Torque'=>'torque','Mileage / range'=>'mileage','Seating'=>'seating','Drive type'=>'drive_type','Safety'=>'safety','Boot space'=>'boot_space'];
$pageTitle='Compare cars';require __DIR__.'/includes/header.php';
?>
<div class="page-intro"><span class="eyebrow">SIDE BY SIDE</span><h1>Compare cars</h1><p class="muted">Compare up to four cars and see the differences clearly.</p></div>
<div class="compare-picker panel"><label for="car-picker">Add a car to comparison</label><div class="picker-row"><select id="car-picker"><option value="">Choose a car</option><?php foreach($all as $a): ?><option value="<?= (int)$a['id'] ?>"><?= e($a['brand'].' '.$a['name']) ?></option><?php endforeach; ?></select><button class="btn" id="add-compare">Add car +</button></div><small class="muted">Choose at least two cars. You can remove any car from the comparison.</small></div>
<?php if($cars): ?><div class="compare-table-wrap panel"><table class="compare-table"><thead><tr><th>Specification</th><?php foreach($cars as $c): ?><th><div class="compare-car"><img src="<?= e(car_image($c['image_url'])) ?>" alt=""><b><?= e($c['name']) ?></b><small><?= e($c['brand']) ?></small><button class="remove-compare" data-remove="<?= (int)$c['id'] ?>">Remove ×</button></div></th><?php endforeach; ?></tr></thead><tbody><?php foreach($fields as $label=>$key): ?><tr><th><?= e($label) ?></th><?php foreach($cars as $c): ?><td><?php if(str_starts_with($key,'price_')): ?><?= money($c[$key]) ?><?php elseif($key==='seating'): ?><?= (int)$c[$key] ?> seats<?php else: ?><?= e((string)$c[$key]) ?><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?><tr><th>Key features</th><?php foreach($cars as $c): ?><td><?= e(implode(' · ', array_slice(json_decode($c['features_json'],true)?:[],0,5))) ?></td><?php endforeach; ?></tr><tr><th>Pros</th><?php foreach($cars as $c): ?><td><?= e(implode(' · ', json_decode($c['pros_json'],true)?:[])) ?></td><?php endforeach; ?></tr><tr><th>Things to consider</th><?php foreach($cars as $c): ?><td><?= e(implode(' · ', json_decode($c['cons_json'],true)?:[])) ?></td><?php endforeach; ?></tr></tbody></table></div><?php else: ?><div class="empty-state">Your comparison is empty. Add cars from this page or tap “+ Compare” on any car card.</div><?php endif; ?>
<div class="compare-note">Prices shown in INR (₹) are indicative ex-showroom reference prices. Actual on-road prices vary by city, variant, insurance and registration.</div>
